komponenten-dropdowns-custom-select--int.snippet:
import { Component } from '@angular/core';
import { SelectComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [SelectComponent],
  template: `
    <cds-select
        [label]="'Bereich'"
        [options]="[{value: 'co', label: 'Corporate'}, {value: 'ki', label: 'Angewandte KI'}, {value: 'es', label: 'Effektive Software'}, {value: 'wo', label: 'Wirksame Organisationen'}]"
        [placeholder]="'Bitte wählen…'"
        [area]="undefined"
        [disabled]="false"
        (disabledChange)="disabledChange($event)"
        (valueChange)="valueChange($event)"
    />`,
})
export class DemoComponent {
  disabledChange(event: unknown) {}
  valueChange(event: unknown) {}
}

