komponenten-dropdowns-custom-select--for.snippet:
import { Component } from '@angular/core';
import { SelectComponent } from '@conciso/design-system-angular';

@Component({
  selector: 'app-demo',
  imports: [SelectComponent],
  template: `
    <div style="display:flex;flex-direction:column;gap:var(--s3);max-width:28rem">
        <cds-select
            label="Bereich"
            [options]="options"
            [formControl]="ctrl">
        </cds-select>
        <p style="font:14px/1.4 system-ui,sans-serif;margin:0">
            Wert:
            <strong>{{ ctrl.value || '(leer)' }}</strong>
        </p>
    </div>`,
})
export class DemoComponent {
  options = [{value: 'co', label: 'Corporate'}, {value: 'ki', label: 'Angewandte KI'}, {value: 'es', label: 'Effektive Software'}, {value: 'wo', label: 'Wirksame Organisationen'}];
}

